XW += x[20]*4.6005000000000003e+01; // NO2
XW += x[21]*3.1014000000000003e+01; // HNO
XW += x[22]*3.1014000000000003e+01; // HON
XW += x[23]*4.7013000000000005e+01; // HONO
XW += x[24]*3.2021999999999998e+01; // H2NO
XW += x[25]*3.2021999999999998e+01; // HNOH
XW += x[26]*4.7013000000000005e+01; // HNO2
XW += x[27]*6.3012000000000000e+01; // HONO2
XW += x[28]*6.2003999999999998e+01; // NO3
XW += x[29]*6.3012000000000000e+01; // HNO3
XW += x[30]*3.3030000000000001e+01; // NH2OH
// Now compute conversion
amrex::Real XWinv = 1.0/XW;
y[0] = x[0]*2.8013999999999999e+01*XWinv; 
y[1] = x[1]*1.0080000000000000e+00*XWinv; 
y[2] = x[2]*2.0160000000000000e+00*XWinv; 
y[3] = x[3]*1.5999000000000001e+01*XWinv; 
