y[10] = x[10]*1.5015000000000001e+01*XWinv; 
y[11] = x[11]*1.6023000000000000e+01*XWinv; 
y[12] = x[12]*1.7030999999999999e+01*XWinv; 
y[13] = x[13]*2.9021999999999998e+01*XWinv; 
y[14] = x[14]*3.0030000000000001e+01*XWinv; 
y[15] = x[15]*3.1038000000000000e+01*XWinv; 
y[16] = x[16]*3.2045999999999999e+01*XWinv; 
y[17] = x[17]*3.0030000000000001e+01*XWinv; 
y[18] = x[18]*3.0006000000000000e+01*XWinv; 
y[19] = x[19]*4.4012999999999998e+01*XWinv; 
y[20] = x[20]*4.6005000000000003e+01*XWinv; 
