y[26] = x[26]*4.7013000000000005e+01*XWinv; 
y[27] = x[27]*6.3012000000000000e+01*XWinv; 
y[28] = x[28]*6.2003999999999998e+01*XWinv; 
y[29] = x[29]*6.3012000000000000e+01*XWinv; 
