// reaction 215: H + HONO2 <=> H2O + NO2
qf[217] = sc[1]*sc[27];
qr[217] = sc[5]*sc[20];

// reaction 216: H + HONO2 <=> HONO + OH
qf[218] = sc[1]*sc[27];
qr[218] = sc[4]*sc[23];

// reaction 217: HONO2 + OH <=> H2O + NO3
qf[219] = sc[4]*sc[27];
