qf[225] = (sc[28] * sc[28]);
qr[225] = sc[8]*(sc[20] * sc[20]);

// compute the mixture concentration
amrex::Real mixture = 0.0;
for (int i = 0; i < 31; ++i) {
mixture += sc[i];
}

// compute the Gibbs free energy
amrex::Real g_RT[31];
gibbs(g_RT, T);

// reference concentration: P_atm / (RT) in inverse mol/m^3
amrex::Real refC = 101325 / 8.31446 * invT;
amrex::Real refCinv = 1 / refC;

// Evaluate the kfs
amrex::Real k_f, Corr;
amrex::Real redP, F, logPred, logFcent, troe_c, troe_n, troe, F_troe;

// reaction 0:  H + O2 <=> O + OH
k_f = 13700000
           * exp((0.2434) * logT - (7266.44865422015) * invT);
qf[30] *= k_f;
qr[30] *= k_f * exp(-(g_RT[1] - g_RT[3] - g_RT[4] + g_RT[8]));
// reaction 1:  H2 + O <=> H + OH
k_f = 1.2554
           * exp((2.27039) * logT - (3500.82802233685) * invT);
qf[31] *= k_f;
qr[31] *= k_f * exp(-(-g_RT[1] + g_RT[2] + g_RT[3] - g_RT[4]));
// reaction 2:  H2 + OH <=> H + H2O
k_f = 216
           * exp((1.51) * logT - (1726.03316371019) * invT);
qf[32] *= k_f;
qr[32] *= k_f * exp(-(-g_RT[1] + g_RT[2] + g_RT[4] - g_RT[5]));
// reaction 3:  2 OH <=> H2O + O
k_f = 13.5
           * exp((1.689) * logT - (-587.153205660947) * invT);
qf[33] *= k_f;
qr[33] *= k_f * exp(-(-g_RT[3] + 2.000000*g_RT[4] - g_RT[5]));
// reaction 4:  2 OH <=> H2O + O
k_f = -26970
           * exp((0.567) * logT);
qf[34] *= k_f;
qr[34] *= k_f * exp(-(-g_RT[3] + 2.000000*g_RT[4] - g_RT[5]));
// reaction 5:  H2 + M <=> 2 H + M
k_f = 45770000000000
           * exp((-1.4) * logT - (52525.7555766966) * invT);
Corr  = mixture + (1.5)*sc[2] + (11)*sc[5];
qf[10] *= Corr * k_f;
qr[10] *= Corr * k_f * exp(-(-2.000000*g_RT[1] + g_RT[2])) * (refCinv);
// reaction 6:  2 O + M <=> O2 + M
k_f = 6165
           * exp((-0.5) * logT);
Corr  = mixture + (1.5)*sc[2] + (11)*sc[5];
qf[11] *= Corr * k_f;
qr[11] *= Corr * k_f * exp(-(2.000000*g_RT[3] - g_RT[8])) * (refC);
// reaction 7:  H + O + M <=> OH + M
k_f = 4714000
           * exp((-1) * logT);
Corr  = mixture + (1.5)*sc[2] + (11)*sc[5];
qf[12] *= Corr * k_f;
qr[12] *= Corr * k_f * exp(-(g_RT[1] + g_RT[3] - g_RT[4])) * (refC);
// reaction 8:  H2O + M <=> H + OH + M
k_f = 6.064e+21
           * exp((-3.322) * logT - (60783.5410625521) * invT);
Corr  = mixture + sc[0] + (2)*sc[2] + (-1)*sc[5] + (0.5)*sc[8];
qf[13] *= Corr * k_f;
qr[13] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[4] + g_RT[5])) * (refCinv);
// reaction 9:  H2O + H2O <=> H + OH + H2O
k_f = 1.006e+20
           * exp((-2.44) * logT - (60476.5788964112) * invT);
qf[14] *= k_f;
qr[14] *= k_f * exp(-(-g_RT[1] - g_RT[4] + g_RT[5])) * (refCinv);
// reaction 10:  H + O2 (+M) <=> HO2 (+M)
k_f = 4650840
           * exp((0.44) * logT);
Corr  = mixture + sc[2] + (13)*sc[5] + (-0.22)*sc[8];
redP = Corr / k_f * 636600000 
           * exp(-1.72  * logT - (264.088106214317) *invT);
F = redP / (1.0 + redP);
logPred = log10(redP);
logFcent = log10(
    (0.5)*exp(-T * 1e+30)
    + 0.5 * exp(-T * 1e-30)
    + 0.0);
troe_c = -0.4 - 0.67 * logFcent;
troe_n = 0.75 - 1.27 * logFcent;
troe = (troe_c + logPred) / (troe_n - 0.14*(troe_c + logPred));
F_troe = exp(M_LN10 * logFcent / (1.0 + troe*troe));
Corr = F * F_troe;
qf[0] *= Corr * k_f;
qr[0] *= Corr * k_f * exp(-(g_RT[1] - g_RT[6] + g_RT[8])) * (refC);
// reaction 11:  H + HO2 <=> H2 + O2
k_f = 2.75
           * exp((2.09) * logT - (-730.167382082648) * invT);
qf[35] *= k_f;
qr[35] *= k_f * exp(-(g_RT[1] - g_RT[2] + g_RT[6] - g_RT[8]));
// reaction 12:  H + HO2 <=> 2 OH
k_f = 70790000
           * exp(-(148.448916412392) * invT);
qf[36] *= k_f;
qr[36] *= k_f * exp(-(g_RT[1] - 2.000000*g_RT[4] + g_RT[6]));
// reaction 13:  HO2 + O <=> O2 + OH
k_f = 28500
           * exp((1) * logT - (-364.293640876011) * invT);
qf[37] *= k_f;
qr[37] *= k_f * exp(-(g_RT[3] - g_RT[4] + g_RT[6] - g_RT[8]));
// reaction 14:  HO2 + OH <=> H2O + O2
k_f = 193000000000000
           * exp((-2.49) * logT - (293.878532829956) * invT);
qf[38] *= k_f;
qr[38] *= k_f * exp(-(g_RT[4] - g_RT[5] + g_RT[6] - g_RT[8]));
// reaction 15:  HO2 + OH <=> H2O + O2
k_f = 1210
           * exp((1.24) * logT - (-659.213832204183) * invT);
qf[39] *= k_f;
qr[39] *= k_f * exp(-(g_RT[4] - g_RT[5] + g_RT[6] - g_RT[8]));
// reaction 16:  2 H + O2 <=> H2 + O2
k_f = 88000000000
           * exp((-1.835) * logT - (402.573332643776) * invT);
qf[15] *= k_f;
qr[15] *= k_f * exp(-(2.000000*g_RT[1] - g_RT[2])) * (refC);
// reaction 17:  2 H + O2 <=> 2 OH
k_f = 40000000000
           * exp((-1.835) * logT - (402.573332643776) * invT);
qf[40] *= k_f;
qr[40] *= k_f * exp(-(2.000000*g_RT[1] - 2.000000*g_RT[4] + g_RT[8])) * (refC);
// reaction 18:  H + O + O2 <=> OH + O2
k_f = 73500000000
           * exp((-1.835) * logT - (402.573332643776) * invT);
qf[16] *= k_f;
qr[16] *= k_f * exp(-(g_RT[1] + g_RT[3] - g_RT[4])) * (refC);
// reaction 19:  H + OH + O2 <=> H2O + O2
k_f = 25600000000
           * exp((-1.835) * logT - (402.573332643776) * invT);
qf[17] *= k_f;
qr[17] *= k_f * exp(-(g_RT[1] + g_RT[4] - g_RT[5])) * (refC);
// reaction 20:  2 HO2 <=> H2O2 + O2
k_f = 1179
           * exp((0.7712) * logT - (-918.370415093613) * invT);
qf[41] *= k_f;
qr[41] *= k_f * exp(-(2.000000*g_RT[6] - g_RT[7] - g_RT[8]));
// reaction 21:  2 HO2 <=> H2O2 + O2
k_f = 1251000
           * exp((0.295) * logT - (3722.29367695751) * invT);
qf[42] *= k_f;
qr[42] *= k_f * exp(-(2.000000*g_RT[6] - g_RT[7] - g_RT[8]));
// reaction 22:  H2O2 (+M) <=> 2 OH (+M)
k_f = 2000000000000
           * exp((0.9) * logT - (24531.3092413143) * invT);
Corr  = mixture + (0.5)*sc[0] + (2.7)*sc[2] + (6.5)*sc[5] + (6.7)*sc[7] + (0.2)*sc[8];
redP = Corr / k_f * 2.49e+18 
           * exp(-2.3  * logT - (24531.3092413143) *invT);
F = redP / (1.0 + redP);
logPred = log10(redP);
logFcent = log10(
    (0.57)*exp(-T * 1e+30)
    + 0.43 * exp(-T * 1e-30)
    + 0.0);
troe_c = -0.4 - 0.67 * logFcent;
troe_n = 0.75 - 1.27 * logFcent;
troe = (troe_c + logPred) / (troe_n - 0.14*(troe_c + logPred));
F_troe = exp(M_LN10 * logFcent / (1.0 + troe*troe));
Corr = F * F_troe;
qf[1] *= Corr * k_f;
qr[1] *= Corr * k_f * exp(-(-2.000000*g_RT[4] + g_RT[7])) * (refCinv);
// reaction 23:  H + H2O2 <=> H2O + OH
k_f = 24100000
           * exp(-(1997.77016324474) * invT);
qf[43] *= k_f;
qr[43] *= k_f * exp(-(g_RT[1] - g_RT[4] - g_RT[5] + g_RT[7]));
// reaction 24:  H + H2O2 <=> H2 + HO2
k_f = 48200000
           * exp(-(4000.57249314752) * invT);
qf[44] *= k_f;
qr[44] *= k_f * exp(-(g_RT[1] - g_RT[2] - g_RT[6] + g_RT[7]));
// reaction 25:  H2O2 + O <=> HO2 + OH
k_f = 9.55
           * exp((2) * logT - (1997.77016324474) * invT);
qf[45] *= k_f;
qr[45] *= k_f * exp(-(g_RT[3] - g_RT[4] - g_RT[6] + g_RT[7]));
// reaction 26:  H2O2 + OH <=> H2O + HO2
k_f = 1740000
           * exp(-(160.022899725901) * invT);
qf[46] *= k_f;
qr[46] *= k_f * exp(-(g_RT[4] - g_RT[5] - g_RT[6] + g_RT[7]));
// reaction 27:  H2O2 + OH <=> H2O + HO2
k_f = 75900000
           * exp(-(3658.38516040031) * invT);
qf[47] *= k_f;
qr[47] *= k_f * exp(-(g_RT[4] - g_RT[5] - g_RT[6] + g_RT[7]));
